/*
 * emihttpd_esp.h - ESP-IDF backend (esp_http_server) of the C server runtime
 * (`emi c --tags esp-server`). The generated action headers only talk to the
 * port declared in emihttpd_core.h; this file implements it.
 *
 * Setup on the server (once):
 *
 *   httpd_config_t config = HTTPD_DEFAULT_CONFIG();
 *   config.uri_match_fn = emihttpd_uri_match;   // understands "/users/:id"
 *   config.max_uri_handlers = 32;
 *   httpd_start(&server, &config);
 *
 * Websocket (reactive) actions additionally need CONFIG_HTTPD_WS_SUPPORT=y.
 *
 * Generated by the Emi compiler - do not edit by hand.
 */
#ifndef EMISDK_EMIHTTPD_ESP_H
#define EMISDK_EMIHTTPD_ESP_H

/* The server side never uses libcurl; the generated path/query helpers only
 * need fetchx.h's url functions. */
#ifndef FETCHX_NO_CURL
#define FETCHX_NO_CURL 1
#endif

#include "esp_http_server.h"
#include "freertos/FreeRTOS.h"
#include "freertos/semphr.h"

typedef SemaphoreHandle_t emihttpd_mutex_t;
static inline int emihttpd_mutex_init(emihttpd_mutex_t* m) { *m = xSemaphoreCreateMutex(); return *m ? 0 : -1; }
static inline void emihttpd_mutex_destroy(emihttpd_mutex_t* m) { if (*m) vSemaphoreDelete(*m); *m = NULL; }
static inline void emihttpd_mutex_lock(emihttpd_mutex_t* m) { xSemaphoreTake(*m, portMAX_DELAY); }
static inline void emihttpd_mutex_unlock(emihttpd_mutex_t* m) { xSemaphoreGive(*m); }

#include "emihttpd_core.h"

typedef httpd_handle_t emihttpd_server_t;
typedef httpd_req_t emihttpd_req_t;
typedef int (*emihttpd_serve_fn)(emihttpd_req_t* req, void* ctx);

typedef struct EmiHttpdEspRoute {
    emihttpd_serve_fn serve;
    EmiHttpdWsHooks hooks;
    void* ctx;
    const char* tmpl;
    httpd_method_t method;
} EmiHttpdEspRoute;

static inline httpd_method_t emihttpd_esp_method(EmiHttpdMethod m) {
    switch (m) {
        case EMIHTTPD_POST: return HTTP_POST;
        case EMIHTTPD_PUT: return HTTP_PUT;
        case EMIHTTPD_PATCH: return HTTP_PATCH;
        case EMIHTTPD_DELETE: return HTTP_DELETE;
        case EMIHTTPD_HEAD: return HTTP_HEAD;
        case EMIHTTPD_OPTIONS: return HTTP_OPTIONS;
        default: return HTTP_GET;
    }
}

static inline esp_err_t emihttpd_esp_http_entry(httpd_req_t* req) {
    EmiHttpdEspRoute* r = (EmiHttpdEspRoute*) req->user_ctx;
    return r->serve(req, r->ctx) == 0 ? ESP_OK : ESP_FAIL;
}

/* Registers a plain route; returns the route handle (NULL on failure). */
static inline void* emihttpd_add_route(emihttpd_server_t server, EmiHttpdMethod method, const char* tmpl,
                                       emihttpd_serve_fn serve, void* ctx) {
    EmiHttpdEspRoute* r = (EmiHttpdEspRoute*) calloc(1, sizeof(*r));
    if (!r) return NULL;
    r->serve = serve;
    r->ctx = ctx;
    r->tmpl = tmpl;
    r->method = emihttpd_esp_method(method);
    httpd_uri_t uri = {
        .uri = tmpl,
        .method = r->method,
        .handler = emihttpd_esp_http_entry,
        .user_ctx = r,
    };
    if (httpd_register_uri_handler(server, &uri) != ESP_OK) { free(r); return NULL; }
    return r;
}

static inline void emihttpd_remove_route(emihttpd_server_t server, void* route) {
    EmiHttpdEspRoute* r = (EmiHttpdEspRoute*) route;
    if (!r) return;
    httpd_unregister_uri_handler(server, r->tmpl, r->method);
    free(r);
}

#ifdef CONFIG_HTTPD_WS_SUPPORT

/* Receives the next frame of a websocket request into a NUL terminated
 * malloc'd payload (free it). Pings are answered here. */
static inline esp_err_t emihttpd_esp_ws_recv(httpd_req_t* req, httpd_ws_frame_t* frame) {
    memset(frame, 0, sizeof(*frame));
    esp_err_t err = httpd_ws_recv_frame(req, frame, 0);
    if (err != ESP_OK) return err;
    if (frame->len > EMIHTTPD_WS_MAX_MESSAGE) return ESP_ERR_NO_MEM;
    uint8_t* payload = (uint8_t*) calloc(1, frame->len + 1);
    if (!payload) return ESP_ERR_NO_MEM;
    frame->payload = payload;
    if (frame->len > 0) {
        err = httpd_ws_recv_frame(req, frame, frame->len);
        if (err != ESP_OK) { free(payload); frame->payload = NULL; return err; }
    }
    if (frame->type == HTTPD_WS_TYPE_PING) {
        httpd_ws_frame_t pong = *frame;
        pong.type = HTTPD_WS_TYPE_PONG;
        httpd_ws_send_frame(req, &pong);
    }
    return ESP_OK;
}

static inline esp_err_t emihttpd_esp_ws_entry(httpd_req_t* req) {
    EmiHttpdEspRoute* r = (EmiHttpdEspRoute*) req->user_ctx;
    int fd = httpd_req_to_sockfd(req);

    if (req->method == HTTP_GET) { /* the handshake */
        if (r->hooks.open && r->hooks.open(req, fd, r->ctx) != 0) return ESP_FAIL;
        return ESP_OK;
    }

    httpd_ws_frame_t frame;
    esp_err_t err = emihttpd_esp_ws_recv(req, &frame);
    if (err != ESP_OK) {
        if (r->hooks.close) r->hooks.close(fd, r->ctx);
        return err;
    }
    if (frame.type == HTTPD_WS_TYPE_CLOSE) {
        if (r->hooks.close) r->hooks.close(fd, r->ctx);
    } else if (frame.type == HTTPD_WS_TYPE_TEXT || frame.type == HTTPD_WS_TYPE_BINARY) {
        if (r->hooks.message) r->hooks.message(fd, frame.type == HTTPD_WS_TYPE_BINARY, frame.payload, frame.len, r->ctx);
    }
    free(frame.payload);
    return ESP_OK;
}

static inline void* emihttpd_add_ws_route(emihttpd_server_t server, const char* tmpl, const EmiHttpdWsHooks* hooks, void* ctx) {
    EmiHttpdEspRoute* r = (EmiHttpdEspRoute*) calloc(1, sizeof(*r));
    if (!r) return NULL;
    r->hooks = *hooks;
    r->ctx = ctx;
    r->tmpl = tmpl;
    r->method = HTTP_GET;
    httpd_uri_t uri = {
        .uri = tmpl,
        .method = HTTP_GET,
        .handler = emihttpd_esp_ws_entry,
        .user_ctx = r,
        .is_websocket = true,
        .handle_ws_control_frames = false,
    };
    if (httpd_register_uri_handler(server, &uri) != ESP_OK) { free(r); return NULL; }
    return r;
}

/* Sends one frame to a connection, safe to call from any task. 0 on success. */
static inline int emihttpd_ws_write(emihttpd_server_t server, emihttpd_conn_t conn, bool binary, const uint8_t* data, size_t len) {
    httpd_ws_frame_t frame;
    memset(&frame, 0, sizeof(frame));
    frame.type = binary ? HTTPD_WS_TYPE_BINARY : HTTPD_WS_TYPE_TEXT;
    frame.payload = (uint8_t*) data;
    frame.len = len;
    return httpd_ws_send_frame_async(server, (int) conn, &frame) == ESP_OK ? 0 : -1;
}

#else
#define EMIHTTPD_NO_WS 1
#endif /* CONFIG_HTTPD_WS_SUPPORT */

/* ---- reading the request --------------------------------------------------------------- */

/* Matches the request path against a template and captures the `:placeholder`
 * values (malloc'd, in order); see emihttpd_path_capture. */
static inline bool emihttpd_req_capture(emihttpd_req_t* req, const char* tmpl, char** out, size_t max, size_t* count) {
    return emihttpd_path_capture(tmpl, req->uri, out, max, count);
}

/* The raw query string (malloc'd) or NULL if there is none. */
static inline char* emihttpd_req_query(emihttpd_req_t* req) {
    size_t len = httpd_req_get_url_query_len(req);
    if (len == 0) return NULL;
    char* qs = (char*) malloc(len + 1);
    if (!qs) return NULL;
    if (httpd_req_get_url_query_str(req, qs, len + 1) != ESP_OK) { free(qs); return NULL; }
    return qs;
}

/* Reads the whole body into a NUL terminated malloc'd buffer. Returns 0 on
 * success (an empty body gives an empty string), -1 when it exceeds
 * EMIHTTPD_MAX_BODY, -2 on a socket error or out of memory. */
static inline int emihttpd_req_body(emihttpd_req_t* req, char** out) {
    *out = NULL;
    size_t total = req->content_len;
    if (total > EMIHTTPD_MAX_BODY) return -1;
    char* buf = (char*) malloc(total + 1);
    if (!buf) return -2;
    size_t got = 0;
    while (got < total) {
        int r = httpd_req_recv(req, buf + got, total - got);
        if (r == HTTPD_SOCK_ERR_TIMEOUT) continue;
        if (r <= 0) { free(buf); return -2; }
        got += (size_t) r;
    }
    buf[got] = '\0';
    *out = buf;
    return 0;
}

/* ---- answering ------------------------------------------------------------------------------ */

/* Sends `json` (may be NULL for an empty body) with the given status. 0 on success. */
static inline int emihttpd_reply_json(emihttpd_req_t* req, int status, const char* json) {
    httpd_resp_set_status(req, emihttpd_status_line(status));
    /* an answer with no body is not a json one: a client which reads the body of "application/json" would fail on it */
    if (json) httpd_resp_set_type(req, "application/json");
    return httpd_resp_send(req, json ? json : "", json ? HTTPD_RESP_USE_STRLEN : 0) == ESP_OK ? 0 : -1;
}

/* Sends `{"error":"<msg>"}` - msg must not need JSON escaping (use plain text). */
static inline int emihttpd_reply_error(emihttpd_req_t* req, int status, const char* msg) {
    char buf[160];
    snprintf(buf, sizeof(buf), "{\"error\":\"%s\"}", msg ? msg : "");
    return emihttpd_reply_json(req, status, buf);
}

#endif /* EMISDK_EMIHTTPD_ESP_H */
